      hxFaq: [{"q":"මම නිෂ්පාදනයක් මිලදී ගන්නේ කෙසේද?","a":"නිෂ්පාදන බලා, ඔබ කැමති එකක් තෝරා ව්‍යවසායිකාව සමඟ WhatsApp හෝ Messenger හරහා කතා කරන්න. ගෙවීම සහ බෙදාහැරීම ඇය සමඟ තහවුරු කරගන්න."},{"q":"ව්‍යවසායිකාවක් ලෙස ලියාපදිංචි විය හැක්කේ කාටද?","a":"කාන්තාවන්ට පමණි. ලියාපදිංචි වීමේදී ඔබේ NIC අංකය අවශ්‍යයි; එයින් ස්ත්‍රී පුරුෂ භාවය සහ උපන් දිනය ස්වයංක්‍රීයව හඳුනාගනී."},{"q":"ලියාපදිංචි වූ පසු කුමක් සිදුවේද?","a":"ඔබේ email එකට කේතයක් එවනු ලැබේ. එය ඇතුළත් කර email එක තහවුරු කරන්න. ඉන් පසු අමාත්‍යාංශය ඔබේ ගිණුම පරීක්ෂා කර අනුමත කරයි."},{"q":"මුරපදය අමතක වුවහොත් කුමක් කරන්නද?","a":"ඇතුල් වීමේ පිටුවේ \"මුරපදය අමතකද?\" තෝරන්න. ඔබේ email එකට එවන කේතය භාවිතයෙන් නව මුරපදයක් තෝරාගත හැක."},{"q":"ව්‍යවසායිකාවක් ගැන පැමිණිලි කරන්නේ කෙසේද?","a":"ඔබේ පාරිභෝගික ගිණුමේ සිට ඇණවුමට අදාළව පැමිණිල්ලක් යොමු කළ හැක. අමාත්‍යාංශය එය පරීක්ෂා කර පිළිතුරු දෙයි."}],
