    faq: {
      title: 'Frequently Asked Questions',
      subtitle: 'Answers to common questions about using the Lanka Women E-Market.',
      search: 'Search for a question...',
      categories: {
        all: 'All',
        buying: 'Buying',
        selling: 'Selling',
        account: 'Account & login',
      },
      noResults: 'No matching questions.',
      clearSearch: 'Clear search',
      stillTitle: 'Still have questions?',
      stillText: "If you can't find your answer here, contact the Ministry and we'll help you.",
      contactBtn: 'Contact us',
      items: [
        { cat: 'buying', q: 'What is the Lanka Women E-Market?', a: 'A national online marketplace run under the Ministry of Women and Child Affairs. It connects women entrepreneurs across Sri Lanka directly with customers, with no middlemen.' },
        { cat: 'buying', q: 'How do I buy a product?', a: 'Find a product you like and tap "{order}". This opens a WhatsApp chat with the seller, where you agree on the price, payment and delivery.' },
        { cat: 'buying', q: 'Do I need an account to buy?', a: 'No. You can browse products and contact sellers without an account. If you like, you can also create a free customer account.' },
        { cat: 'buying', q: 'How do I pay?', a: 'You pay the seller directly, in the way you both agree on (for example bank transfer or cash on delivery). The website itself does not take payments or store card details.' },
        { cat: 'buying', q: 'How does delivery work?', a: 'Delivery is arranged between you and the seller. Delivery options, times and charges depend on the seller, so ask about them on WhatsApp before you order.' },
        { cat: 'buying', q: 'Can I trust the sellers?', a: "Every seller registers with her NIC number, and her products only appear on the website after the Ministry approves her account. Still, confirm the product details with the seller before you pay." },
        { cat: 'buying', q: 'What does "{priceOnRequest}" mean?', a: "The seller hasn't listed a price for that product. Ask the seller for the price on WhatsApp." },
        { cat: 'buying', q: 'What if there is a problem with my order?', a: "First contact the seller on WhatsApp. If you can't solve it together, contact the Ministry using the phone number or email at the bottom of this page." },
        { cat: 'selling', q: 'Who can sell on the platform?', a: 'Sri Lankan women entrepreneurs running a micro or small business, such as handicrafts, textiles, agri-products, food and spices, or beauty products. You need a valid NIC number to register.' },
        { cat: 'selling', q: 'How do I register as a seller?', a: 'Click "{register}", choose "{seller}" and fill in your personal, business and contact details. Your account is ready straight away and you can start adding products.' },
        { cat: 'selling', q: 'Does it cost anything to sell here?', a: 'No. Registering, listing your products and the e-learning courses are all free.' },
        { cat: 'selling', q: 'When will my products appear on the website?', a: 'After the Ministry approves your seller account. Your dashboard shows your status: "{pending}", "{approved}" or "{rejected}". You can add products while you wait.' },
        { cat: 'selling', q: 'How do I add or remove products?', a: 'Log in and open your dashboard. Use "{addProduct}" to add a new product, and "{remove}" next to a product to take it off the website.' },
        { cat: 'selling', q: 'How will customers contact me?', a: 'When a customer taps "{order}" on one of your products, a chat opens with the WhatsApp number you gave when registering. Your dashboard shows how many customers did this, in total and in the last 7 days.' },
        { cat: 'selling', q: 'Where can I learn to grow my business?', a: 'Visit the "{elearn}" for free courses on topics such as selling with WhatsApp Business, pricing your products and product photography.' },
        { cat: 'account', q: 'How do I log in?', a: 'Click "{login}", choose "{seller}" or "{customer}", and enter your email and NIC number. We email you a 6-digit code; type it in to log in. You never need a password.' },
        { cat: 'account', q: "I didn't get the login code. What should I do?", a: 'Check your spam or junk folder, and make sure you used the same email you registered with. You can ask for a new code after 60 seconds. Each code is valid for 10 minutes.' },
        { cat: 'account', q: 'Is my personal information safe?', a: "Your NIC number is only used to confirm who you are and to log you in; it is never shown on the website. A seller's WhatsApp number is shown to customers so they can place orders." },
        { cat: 'account', q: 'How do I change my email or phone number?', a: 'Log in and open "{dashboard}" (sellers) or "{myAccount}" (customers). Under "{contactTitle}", click "{change}" next to your email or phone number. A new email only takes effect after you type in the code we send to it.' },
      ],
    },
