      hxFaq: [{"q":"ஒரு பொருளை எப்படி வாங்குவது?","a":"பொருட்களைப் பார்த்து, விரும்புவதைத் தேர்ந்தெடுத்து விற்பனையாளருடன் WhatsApp அல்லது Messenger மூலம் பேசுங்கள். கட்டணம் மற்றும் விநியோகத்தை அவருடன் உறுதிப்படுத்துங்கள்."},{"q":"யார் விற்பனையாளராகப் பதிவு செய்யலாம்?","a":"பெண்கள் மட்டுமே. பதிவுக்கு உங்கள் NIC எண் தேவை; அதன் மூலம் தகுதி உறுதிசெய்யப்பட்டு பிறந்த திகதி தானாக நிரப்பப்படும்."},{"q":"பதிவு செய்த பிறகு என்ன நடக்கும்?","a":"உங்கள் மின்னஞ்சலுக்கு ஒரு குறியீடு அனுப்பப்படும். அதை உள்ளிட்டு மின்னஞ்சலை உறுதிப்படுத்துங்கள். பின்னர் அமைச்சு உங்கள் கணக்கை பரிசீலித்து அங்கீகரிக்கும்."},{"q":"கடவுச்சொல்லை மறந்துவிட்டால் என்ன செய்வது?","a":"உள்நுழைவுப் பக்கத்தில் \"கடவுச்சொல் மறந்துவிட்டதா?\" என்பதைத் தேர்ந்தெடுக்கவும். மின்னஞ்சலில் வரும் குறியீடு மூலம் புதிய கடவுச்சொல்லை அமைக்கலாம்."},{"q":"விற்பனையாளர் பற்றி புகார் செய்வது எப்படி?","a":"உங்கள் வாடிக்கையாளர் கணக்கிலிருந்து ஆர்டர் தொடர்பான புகாரை அனுப்பலாம். அமைச்சு அதைப் பரிசீலித்து பதிலளிக்கும்."}],
